### Python

```python
import sys

# 预计算 10 的幂
POW10 = [1]
for _ in range(19):
    POW10.append(POW10[-1] * 10)

def rev_int(x, k):
    """把 k 位整数 x 翻转（十进制），返回整数"""
    r = 0
    for _ in range(k):
        r = r * 10 + x % 10
        x //= 10
    return r

def make_num(a, k):
    """由 A 与 k 构造 A + rev(A) + A 的数值"""
    return a * POW10[2 * k] + rev_int(a, k) * POW10[k] + a

def count_leq(x):
    """<= x 的超级回文个数"""
    if x < 0:
        return 0
    s = str(x)
    n = len(s)
    ans = 0
    for k in range(1, 7):  # 3k <= 18
        if 3 * k < n:
            ans += 9 * POW10[k - 1]
        elif 3 * k == n:
            lo = POW10[k - 1]
            hi = POW10[k] - 1
            # 二分最大 A
            L, R, best = lo, hi, lo - 1
            while L <= R:
                mid = (L + R) // 2
                val = make_num(mid, k)
                if val <= x:
                    best = mid
                    L = mid + 1
                else:
                    R = mid - 1
            if best >= lo:
                ans += best - lo + 1
    return ans

def main():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    T = int(next(it))
    out = []
    for _ in range(T):
        l = int(next(it)); r = int(next(it))
        out.append(str(count_leq(r) - count_leq(l - 1)))
    print("\n".join(out))

if __name__ == "__main__":
    main()
```

